+            assertThat(i + ": " + point, result.getMinY(), equalTo(minY));
+            assertThat(i + ": " + point, result.getMaxX(), equalTo(maxX));
+            assertThat(i + ": " + point, result.getMaxY(), equalTo(maxY));
